import broadcastScalar = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	broadcastScalar( [ 2, 2 ], 1.0 ); // $ExpectType typedndarray<number>

	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'float64' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'float32' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'complex128' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'complex64' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], true, { 'dtype': 'bool' } ); // $ExpectType genericndarray<boolean>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'int32' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'int16' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'int8' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'uint32' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'uint16' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'uint8' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'uint8c' } ); // $ExpectType typedndarray<number>
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 'generic' } ); // $ExpectType typedndarray<number>
}

// The compiler throws an error if the function is provided a first argument which is not an array of integers...
{
	broadcastScalar( '10', 1.0 ); // $ExpectError
	broadcastScalar( 5, 1.0 ); // $ExpectError
	broadcastScalar( false, 1.0 ); // $ExpectError
	broadcastScalar( true, 1.0 ); // $ExpectError
	broadcastScalar( null, 1.0 ); // $ExpectError
	broadcastScalar( ( x: number ): number => x, 1.0 ); // $ExpectError

	broadcastScalar( '10', 1.0, {} ); // $ExpectError
	broadcastScalar( 5, 1.0, {} ); // $ExpectError
	broadcastScalar( false, 1.0, {} ); // $ExpectError
	broadcastScalar( true, 1.0, {} ); // $ExpectError
	broadcastScalar( null, 1.0, {} ); // $ExpectError
	broadcastScalar( ( x: number ): number => x, 1.0, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	broadcastScalar( [ 2, 2 ], 1.0, '10' ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, 5 ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, false ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, true ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, null ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, [] ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a `dtype` option which is not a recognized/supported data type...
{
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': '10' } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': 5 } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': false } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': true } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': null } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': [] } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': {} } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'dtype': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided an `order` option which is not a recognized/supported data order...
{
	broadcastScalar( [ 2, 2 ], 1.0, { 'order': '10' } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'order': 5 } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'order': false } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'order': true } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'order': null } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'order': [] } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'order': {} } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'order': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `readonly` option which is not a boolean...
{
	broadcastScalar( [ 2, 2 ], 1.0, { 'readonly': '10' } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'readonly': 5 } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'readonly': null } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'readonly': [] } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'readonly': {} } ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, { 'readonly': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	broadcastScalar(); // $ExpectError
	broadcastScalar( [ 2, 2 ] ); // $ExpectError
	broadcastScalar( [ 2, 2 ], 1.0, {}, {} ); // $ExpectError
}
